<script>
let dashBusy=false;
async function loadDash(){if(dashBusy)return;dashBusy=true;try{const [bj,vj]=await Promise.all([vsJsonFetch('api/bookings/history.php'),fetch('api/vehicles/').then(r=>r.json())]);const a=bj.data||[],v=vj.data||[],count=s=>a.filter(x=>x.status===s).length;stats.innerHTML=`<div class="stat"><span>Available vehicles</span><b>${v.filter(x=>x.status==='Available').length}</b></div><div class="stat"><span>Pending requests</span><b>${count('Pending')}</b></div><div class="stat"><span>Payment due</span><b>${count('Approved')}</b></div><div class="stat"><span>Confirmed</span><b>${count('Confirmed')}</b></div><div class="stat"><span>Active rentals</span><b>${count('Active')}</b></div><div class="stat"><span>Completed</span><b>${count('Completed')}</b></div>`;recent.innerHTML=a.length?`<div class="mini-list">${a.slice(0,5).map(b=>`<div><strong>${b.vehicleName}</strong><span>${b.startDate} → ${b.endDate}</span><em class="badge ${b.status.toLowerCase()}">${b.status}</em></div>`).join('')}</div>`:'<div class="empty-card">No bookings yet. Start by exploring our fleet.</div>';}catch(e){}finally{dashBusy=false}}
loadDash();setInterval(()=>{if(!document.hidden)loadDash()},8000);
</script><?php require_once 'includes/footer.php';?>
